-- Kenya deep-dive + milestone ES/DE/FR translations, completing 455
-- (deep-dive content) and 453 (milestones) against their English content
-- (7 Aug 2026). Pattern reference: 442 (Kazakhstan translations).
-- This is a SEPARATE migration file, so every deep-dive translation row
-- looks up its parent row via a JOIN on stable identifying columns
-- (country code / section / sort_order), never via (SELECT MAX(id) ...).
-- milestone_translations has a natural PK on (milestone_id, lang), so
-- those rows are plain INSERT OR IGNORE statements keyed on the
-- hardcoded milestone id strings from 453 -- no JOIN needed. INSERT OR
-- IGNORE throughout. Every proper noun and kept-as-is token (KRA, eTIMS,
-- TIMS, iTax, eCitizen, OSCU, VSCU, PIN, USSD *222#, QR, KES amounts,
-- URLs, English law names: Finance Act 2023/2026, Tax Procedures Act,
-- Income Tax Act, VAT Act, the 2020/2024 Regulations, the two 2024
-- Amendment Acts, Legal Notice numbers) is preserved from the English
-- source, with a translated gloss on first use where natural; only the
-- surrounding prose is translated. Sourcing caveats ("not verified",
-- "plausible, not confirmed", etc.) are translated but kept exactly as
-- hedged as the English -- never softened or dropped.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es',
  'Evolución CTC de dispositivos a software: facturación fiscal electrónica obligatoria para las empresas del IVA desde 2022 (TIMS), ampliada a TODAS las empresas mediante eTIMS desde septiembre de 2023, y aplicada a través de la deducibilidad de los gastos y la validación automatizada de las declaraciones, más que mediante el bloqueo de la validez de las facturas',
  'Esta página de análisis refleja la Tax Procedures Act (Ley de Procedimientos Tributarios), la VAT Act (Ley del IVA) y los reglamentos de aplicación de Kenia, confirmados a través de los propios avisos, preguntas frecuentes y guías de la Kenya Revenue Authority, junto con alertas fiscales de las Big-4 para los cambios de rango legal, con fecha de principios de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal o tributaria. Confirme los requisitos vigentes directamente con la KRA (kra.go.ke), los canales de soporte de eTIMS o un asesor fiscal keniano antes de basar en esta página sus decisiones de cumplimiento.',
  'El camino de Kenia va desde las cajas registradoras fiscales con memoria fiscal (Electronic Tax Registers, 2005), pasando por los dispositivos TIMS conectados a internet (reglamento publicado en septiembre de 2020, despliegue desde agosto de 2021, fecha límite definitiva el 30 de noviembre de 2022), hasta la plataforma de software eTIMS: aplicaciones gratuitas, un portal, USSD y API que transmiten cada factura a la KRA en tiempo real o casi real. La Finance Act 2023 (Ley de Finanzas de 2023) amplió la obligación más allá de las empresas registradas a efectos del IVA a toda persona con actividad empresarial desde el 1 de septiembre de 2023, y desde el 1 de enero de 2026 la KRA valida las declaraciones del impuesto sobre la renta línea por línea contra los datos resultantes.',
  'Una factura fiscal electrónica keniana conforme se genera a través de un canal controlado por la KRA (portal eTIMS, aplicación, USSD o una integración de sistemas OSCU/VSCU) y se transmite a la KRA en el momento de la emisión. El contenido obligatorio incluye el PIN del vendedor, el PIN del comprador cuando este vaya a deducir el gasto o el IVA soportado, identificadores únicos de sistema y de factura, y un código QR de verificación. La KRA documenta la transmisión como en tiempo real o casi real; aquí no se afirma el formato técnico exacto, ya que las fuentes públicas se contradicen (véase la nota más abajo).',
  'Desde el 1 de septiembre de 2023 la obligación cubre a toda persona que ejerza una actividad empresarial en Kenia -- sociedades, partnerships y empresarios individuales, incluidos quienes tributan solo por rentas de alquiler, impuesto sobre el volumen de negocios o impuesto sobre la renta, no solo los registrados a efectos del IVA. Las empresas con una facturación anual igual o inferior a KES 5 millones no están obligadas a incorporarse directamente: sus compradores empresariales deben, en cambio, autoemitir facturas inversas (iniciadas por el comprador) por esas compras. Los tipos de transacción excluidos incluyen retribuciones salariales, importaciones, intereses, billetes de avión, pagos sujetos a retención liberatoria y suministros de no residentes sin establecimiento permanente en Kenia.',
  'Toda empresa que opere en Kenia debería estar ya en eTIMS -- la ventana de incorporación sin sanciones se cerró el 31 de marzo de 2024. La cuestión de cumplimiento vigente es la calidad de los datos: desde el 1 de enero de 2026 la KRA valida los ingresos y gastos declarados contra los registros de eTIMS, retenciones y aduanas, de modo que conciliar sus libros con los datos de eTIMS antes de presentar la declaración, y rechazar durante el año las facturas de proveedores no conformes, es ahora la disciplina esencial.',
  'Kenia hace cumplir el régimen menos mediante el bloqueo de la validez de las facturas que a través del dinero: una sanción legal del doble del impuesto adeudado por incumplimiento, la denegación de deducciones en el impuesto sobre la renta para gastos sin factura eTIMS (desde enero de 2024), la denegación de deducciones del IVA soportado, la retención de los certificados de cumplimiento tributario (Tax Compliance Certificates) y -- desde enero de 2026 -- el rechazo automatizado en el momento de la presentación cuando las cifras declaradas no coinciden con los datos de eTIMS.',
  'Kenia exige facturas fiscales electrónicas a todas las empresas registradas a efectos del IVA desde el 30 de noviembre de 2022 (TIMS), y a TODAS las empresas -- incluidas las no registradas a efectos del IVA -- desde el 1 de septiembre de 2023 (eTIMS, mediante canales gratuitos de portal, aplicación, USSD y API). La aplicación es financiera más que basada en la validez: los gastos sin factura eTIMS no son deducibles desde enero de 2024, y desde el 1 de enero de 2026 la KRA coteja cada declaración del impuesto sobre la renta con los datos de facturas de eTIMS, los registros de retenciones y las importaciones aduaneras. Los proveedores pequeños (facturación <= KES 5 millones) quedan cubiertos indirectamente mediante la facturación obligatoria iniciada por el comprador.',
  '🇰🇪'
FROM countries WHERE code = 'KE';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '30 nov 2022', 'Facturas fiscales electrónicas obligatorias para todas las empresas registradas a efectos del IVA (TIMS)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 sep 2023', 'La obligación se extiende a TODAS las empresas, incluidas las no registradas a efectos del IVA (eTIMS)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2024', 'Los gastos sin factura eTIMS dejan de ser deducibles en el impuesto sobre la renta' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '508.413', 'Contribuyentes incorporados a eTIMS a 30 de septiembre de 2025 (KRA; objetivo: 1 millón)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2026', 'La KRA valida las declaraciones del impuesto sobre la renta contra datos de eTIMS, retenciones y aduanas' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y modelo de transmisión', '[["Generación de la factura", "A través de un canal eTIMS controlado por la KRA (portal, aplicación, USSD o integración de sistemas OSCU/VSCU) -- no una salida libre del ERP"], ["Transmisión", "En tiempo real o casi real a la KRA en el momento de la emisión (descripción de la propia KRA)"], ["Contenido obligatorio", "PIN del vendedor; PIN del comprador (cuando el comprador deduce el gasto/IVA soportado); número de serie; fecha y hora de emisión y de entrega; código del artículo, descripción, cantidad, unidad; tipo impositivo; totales; identificadores únicos de sistema y de factura; código QR"], ["Verificación", "El código QR permite a cualquier cliente verificar la validez de la factura ante la KRA"]]', 'Las fuentes públicas se contradicen sobre el formato técnico exacto (XML estructurado según un informe sectorial frente a una API REST JSON según la documentación de integradores) -- esta página deliberadamente no se compromete con ninguno. Lo confirmado es el canal de generación controlado por la KRA y la transmisión en el momento de la emisión.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Canales de solución (todos gratuitos de la KRA)', '[["eTIMS Online Portal", "etims.kra.go.ke -- empresas de servicios que emiten <= 10 facturas al mes"], ["eTIMS Client", "Software para Windows/Android para empresas de bienes y mixtas; admite varias sucursales y cajas"], ["eTIMS Lite", "Para contribuyentes no registrados a efectos del IVA: web mediante eCitizen, aplicación móvil o USSD *222# (sin necesidad de internet)"], ["Integración de sistemas", "OSCU (alojado por la KRA, sistemas en línea) o VSCU (alojado por el cliente, alto volumen) mediante API; sandbox en etims-sbx.kra.go.ke"], ["Facturación inversa", "Facturación iniciada por el comprador para las compras a proveedores pequeños (facturación <= KES 5 millones)"]]', 'Desde febrero de 2025 la incorporación es totalmente autoservicio y una empresa puede utilizar varias soluciones simultáneamente (comunicado de prensa de la KRA). El software es gratuito; pueden aplicarse tarifas de integradores terceros.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Quién debe cumplir', '[["Todas las empresas (desde el 1 sep 2023)", "Toda persona con actividad empresarial -- sociedades, partnerships, empresarios individuales, incl. quienes tributan solo por rentas de alquiler, impuesto sobre el volumen de negocios o impuesto sobre la renta (art. 23A de la TPA, Finance Act 2023)"], ["Empresas registradas a efectos del IVA", "Bajo mandato desde el 30 nov 2022 (TIMS); solo las facturas electrónicas sustentan deducciones del IVA soportado desde el 1 jun 2023"], ["Proveedores pequeños (facturación <= KES 5 millones)", "Sin obligación de incorporación directa -- los compradores empresariales deben autoemitir facturas inversas en su lugar (obligatorio desde el 27 dic 2024)"], ["Transacciones excluidas", "Retribuciones salariales, importaciones, intereses, billetes de avión, pagos con retención liberatoria, suministros de no residentes sin establecimiento permanente keniano"], ["Proveedores digitales no residentes", "Exentos del sistema eTIMS en sí, pero deben seguir emitiendo facturas que muestren el valor y el impuesto"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de la factura', 'Una factura electrónica keniana conforme sigue esta secuencia:', 'La resiliencia sin conexión está integrada: eTIMS Client y VSCU siguen facturando durante las pérdidas de conectividad y transmiten al reconectarse; un fallo del sistema debe notificarse a la KRA por escrito en un plazo de 24 horas.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Genere la factura en un canal eTIMS (portal, aplicación, USSD o sistema integrado)' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Los datos de la factura se validan y transmiten a la KRA en tiempo real o casi real, con identificadores únicos y código QR aplicados' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El comprador recibe la factura conforme -- con el PIN del comprador cuando vaya a seguir una deducción o un crédito de IVA soportado' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Los datos transmitidos alimentan las declaraciones del IVA precumplimentadas y los registros de la KRA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Desde el 1 ene 2026: las declaraciones del impuesto sobre la renta se validan contra los datos de ventas/compras de eTIMS, los registros de retenciones y las importaciones aduaneras' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Sanciones legales', '[["Incumplimiento de la obligación de facturación electrónica", "Sanción del doble del impuesto adeudado (Finance Act 2023)"], ["No integrarse con el sistema de datos de la KRA cuando se exige (> KES 5 millones de facturación)", "Hasta KES 100.000 al mes (Tax Laws (Amendment) Act 2024)"], ["Gestión de fallos del sistema", "Notificación por escrito a la KRA en 24 horas; ventas registradas por los medios alternativos prescritos (Regulations 2024)"]]', 'El artículo legal de la sanción del doble del impuesto adeudado se cita habitualmente como el art. 86 de la TPA, pero no se verificó contra el texto consolidado de la ley en esta ronda de investigación -- el importe de la sanción en sí está confirmado mediante el análisis de las Big-4 de la Finance Act 2023.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'La red de aplicación financiera', '[["Deducciones del impuesto sobre la renta", "Los gastos sin factura generada por eTIMS no son deducibles (art. 16(1)(c) de la ITA, desde el 1 ene 2024)"], ["IVA soportado", "Solo las facturas fiscales electrónicas sustentan deducciones y devoluciones del IVA soportado (aplicado desde el 1 jun 2023)"], ["Tax Compliance Certificates", "Se retienen a los contribuyentes incumplidores -- un obstáculo práctico para licitaciones y relaciones bancarias"], ["Validación de declaraciones (desde el 1 ene 2026)", "La KRA toma el mayor entre los ingresos declarados y los de eTIMS, y el menor entre los gastos declarados y los de eTIMS -- los importes sin respaldo se enfrentan a un rechazo administrativo al presentar"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔍 Lo que no pudimos confirmar', '[["Suavización de sanciones de la Finance Act 2026", "Un cambio comunicado del doble del impuesto adeudado al 5 % del impuesto adeudado (mín. KES 100.000 sociedades / KES 10.000 personas físicas) se remonta a un único análisis de un bufete de abogados -- trátese como plausible, no confirmado"], ["Formato técnico exacto", "XML frente a API JSON -- las fuentes se contradicen; sin resolver"], ["Fecha del mandato de declaraciones del IVA precumplimentadas", "La supuesta fecha obligatoria del 1 ene 2025 solo tiene fuentes secundarias (la cifra de la KRA de 162.000 usuarios de la declaración automatizada está confirmada, la fecha del mandato no)"], ["Período de archivo", "Un período de conservación digital de 5 años se cita en el sector, pero en esta ronda no se encontró ninguna página de la KRA que lo confirme"]]', 'Los elementos aquí recogidos quedan excluidos de la cronología de hitos y del resumen anterior conforme al estándar de fuentes de este sitio -- se enumeran para que sepa qué verificar dos veces, en lugar de omitirse en silencio.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Regístrese en eTIMS', 'Inscríbase en etims.kra.go.ke con su PIN de la KRA (credenciales de iTax). Los contribuyentes pequeños o no registrados a efectos del IVA pueden usar en su lugar eTIMS Lite a través de eCitizen en la web, la aplicación móvil o USSD *222# sin conexión a internet.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Elija su solución y presente la solicitud de servicio', 'Seleccione el canal que se ajuste a su negocio (portal, eTIMS Client, Lite o integración de sistemas) y presente la solicitud de servicio con el formulario de compromiso firmado y una copia del documento de identidad del director o propietario. La incorporación es totalmente autoservicio desde febrero de 2025, y puede utilizar varias soluciones a la vez.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', '¿Se integra? Pruebe primero en el sandbox', 'Las integraciones de sistema a sistema (OSCU para alojamiento en la KRA, VSCU para alto volumen alojado por el cliente) deben probarse contra el sandbox en etims-sbx.kra.go.ke antes de la aprobación para producción, que se confirma por SMS.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Cuide los detalles de los datos', 'Configure las plantillas de factura con el contenido obligatorio -- especialmente el PIN del comprador en cualquier factura que este vaya a usar para una deducción o un crédito de IVA soportado -- y configure la facturación iniciada por el comprador para las compras a proveedores pequeños. Forme al personal de ventas y de cuentas a pagar/cobrar: un PIN ausente le cuesta ahora dinero real a su cliente.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Concilie antes de presentar', 'Desde el 1 de enero de 2026 la KRA valida las declaraciones contra los datos de eTIMS automáticamente. Concilie sus libros con los registros de ventas y compras de eTIMS a lo largo del año -- y reclame a los proveedores las facturas electrónicas conformes cuando se produce el gasto, no en el momento de la presentación.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Portal del contribuyente eTIMS' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'iTax (presentación de declaraciones)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'KRA -- guía de soluciones eTIMS' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 2;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-tims-regulations-2020', 'es',
  'Publicado en el boletín oficial el reglamento de la factura fiscal electrónica (TIMS)',
  'Las VAT (Electronic Tax Invoice) Regulations, 2020 (Reglamento del IVA sobre la Factura Fiscal Electrónica; Legal Notice N.º 189, de 25 de septiembre de 2020) crearon la base legal del Tax Invoice Management System (TIMS) de Kenia: las empresas registradas a efectos del IVA tendrían que sustituir sus antiguas cajas registradoras fiscales con memoria fiscal (Electronic Tax Registers, en uso desde 2005) por dispositivos conectados a internet que validan cada factura y la transmiten a la Kenya Revenue Authority (KRA) en tiempo real o casi real. El despliegue propiamente dicho comenzó el 1 de agosto de 2021 con una ventana de migración de 12 meses.',
  '["Ninguna obligación inmediata en el momento de la publicación -- la ventana de migración se abrió el 1 de agosto de 2021.", "Las empresas registradas a efectos del IVA debían planificar la actualización a un dispositivo ETR conforme con TIMS (tipos A-D, según el tipo de negocio y el volumen)."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-tims-mandatory-2022', 'es',
  'Facturas fiscales electrónicas obligatorias para todas las empresas registradas a efectos del IVA',
  'Tras una ventana de migración de un año (desde el 1 de agosto de 2021) y una prórroga anunciada por aviso público, el 30 de noviembre de 2022 fue la fecha límite definitiva para que toda empresa registrada a efectos del IVA en Kenia emitiera facturas fiscales electrónicas a través de dispositivos conformes con TIMS, validadas y transmitidas a la KRA en el momento de la emisión. Desde el 1 de junio de 2023 la KRA aplica el régimen con rigor: solo las facturas fiscales electrónicas se aceptan para sustentar deducciones del IVA soportado y devoluciones, y a los contribuyentes incumplidores se les retienen los certificados de cumplimiento tributario (Tax Compliance Certificates).',
  '["Confirme que todos sus sistemas de venta emiten facturas a través de TIMS/eTIMS con validación de la KRA.", "Compruebe que las facturas recibidas de proveedores son facturas fiscales electrónicas válidas -- las facturas de compra no conformes no pueden sustentar deducciones del IVA soportado.", "Si existe una brecha de cumplimiento, contacte con la KRA cuanto antes: los Tax Compliance Certificates se retienen a las empresas incumplidoras."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-etims-all-businesses-2023', 'es',
  'eTIMS se amplía a TODAS las empresas -- incluidas las no registradas a efectos del IVA',
  'La Finance Act 2023 (Ley de Finanzas de 2023) introdujo el artículo 23A en la Tax Procedures Act (Ley de Procedimientos Tributarios), ampliando la obligación de factura fiscal electrónica más allá de los contribuyentes registrados a efectos del IVA a toda persona que ejerza una actividad empresarial en Kenia -- sociedades, partnerships y empresarios individuales, incluidos quienes tributan solo por rentas de alquiler, impuesto sobre el volumen de negocios o impuesto sobre la renta -- con efectos desde el 1 de septiembre de 2023. Los canales de software gratuitos de eTIMS de la KRA (portal, aplicación, USSD *222# mediante eTIMS Lite) eliminaron la necesidad de dispositivos físicos, con una ventana de incorporación sin sanciones para las empresas no registradas a efectos del IVA que se cerró el 31 de marzo de 2024. Las empresas con una facturación igual o inferior a KES 5 millones no están obligadas a incorporarse directamente -- en su lugar, sus compradores deben registrar la compra mediante facturación inversa (iniciada por el comprador).',
  '["Toda empresa -- registrada o no a efectos del IVA -- debería estar incorporada a eTIMS (portal, aplicación, eCitizen Lite o USSD *222#).", "Proveedores pequeños (facturación <= KES 5 millones): espere que sus compradores empresariales autoemitan facturas inversas por las compras que le hagan.", "Los compradores que adquieran de proveedores pequeños no incorporados deben generar facturas iniciadas por el comprador a través de eTIMS."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-deductibility-2024', 'es',
  'Sin factura eTIMS no hay deducción fiscal',
  'Desde el 1 de enero de 2024, el artículo 16(1)(c) de la Income Tax Act (Ley del Impuesto sobre la Renta), modificada por la Finance Act 2023, rechaza cualquier gasto empresarial que no esté respaldado por una factura fiscal electrónica generada a través de TIMS/eTIMS. Es el mecanismo de aplicación más contundente de Kenia: en lugar de vigilar solo a los emisores, convierte a cada comprador empresarial en garante del cumplimiento, porque una factura en papel o no conforme de un proveedor le cuesta ahora al comprador la deducción en el impuesto sobre la renta de todo ese gasto.',
  '["Rechace las facturas de proveedores que no hayan sido generadas por eTIMS -- le cuestan la deducción en el impuesto sobre la renta.", "Asegúrese de que sus propias facturas incluyan el PIN del comprador cuando este vaya a deducir el gasto.", "Concilie sus registros de gastos con los datos de compras de eTIMS antes de presentar las declaraciones del impuesto sobre la renta."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-eti-regulations-2024', 'es',
  'Publicado el reglamento de la factura fiscal electrónica de 2024',
  'Las Tax Procedures (Electronic Tax Invoice) Regulations, 2024 (Reglamento de Procedimientos Tributarios sobre la Factura Fiscal Electrónica; Legal Notice N.º 64, publicado el 3 de mayo de 2024) codificaron el detalle operativo del régimen eTIMS: contenido obligatorio de la factura (PIN del vendedor, PIN del comprador cuando este vaya a deducir el gasto, identificadores únicos de sistema y de factura, código QR), una regla de notificación por escrito en 24 horas para fallos del sistema, y las exclusiones de alcance (retribuciones salariales, importaciones, intereses, billetes de avión, pagos sujetos a retención liberatoria y suministros de no residentes sin establecimiento permanente en Kenia). Cabe destacar que se descartó un proyecto de exención total para las empresas con menos de KES 5 millones de facturación -- la obligación se traslada en cambio al comprador.',
  '["Verifique que sus plantillas de factura incluyen todos los campos de contenido obligatorios, incluidos el código QR y el PIN del comprador cuando proceda.", "Establezca un proceso de notificación a la KRA en 24 horas para caídas del sistema.", "Identifique cuáles de sus tipos de transacción entran en las exclusiones del reglamento."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-reverse-invoicing-2024', 'es',
  'Facturación iniciada por el comprador obligatoria para las compras a proveedores pequeños',
  'La Tax Procedures (Amendment) Act 2024 y la Tax Laws (Amendment) Act 2024 (ambas con efectos desde el 27 de diciembre de 2024) formalizaron la facturación inversa: los compradores empresariales deben autoemitir facturas electrónicas a través de eTIMS por las compras a proveedores con una facturación anual igual o inferior a KES 5 millones, y la KRA obtuvo la facultad de exigir la integración de sistemas de datos a las empresas con más de KES 5 millones de facturación, respaldada por una sanción de hasta KES 100.000 al mes por no integrarse.',
  '["Si compra a proveedores pequeños, configure en eTIMS la facturación iniciada por el comprador para esas compras.", "Empresas con más de KES 5 millones de facturación: prepárense para la integración de sistemas exigida por la KRA si aún no están integradas."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-return-validation-2026', 'es',
  'La KRA coteja cada declaración del impuesto sobre la renta con los datos de eTIMS',
  'Conforme a un aviso público de la KRA del 10 de noviembre de 2025, desde el 1 de enero de 2026 los ingresos y gastos declarados en las declaraciones del impuesto sobre la renta (a partir del ejercicio fiscal 2025) se validan contra los datos de facturas de TIMS/eTIMS, los registros de retenciones y los registros aduaneros de importación. En la práctica, la KRA toma el mayor entre los ingresos declarados y los datos de ventas de eTIMS, y el menor entre los gastos declarados y los datos de compras de eTIMS -- de modo que los gastos sin respaldo se enfrentan a un rechazo administrativo en el momento de la presentación. Esto pone en práctica, a escala nacional, la regla de "sin factura eTIMS no hay deducción" vigente desde enero de 2024.',
  '["Concilie sus libros con los datos de ventas y compras de eTIMS ANTES de presentar la declaración -- las discrepancias ahora afloran automáticamente.", "Reclame a los proveedores las facturas electrónicas conformes durante el año, no en el momento de la presentación.", "Confirme que los créditos por retenciones y los registros aduaneros de importación coinciden con sus cifras declaradas."]'
);

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de',
  'CTC-Entwicklung vom Gerät zur Software: elektronische Steuerrechnungen für MwSt.-Unternehmen seit 2022 verpflichtend (TIMS), ab September 2023 über eTIMS auf ALLE Unternehmen ausgeweitet, durchgesetzt über die Abzugsfähigkeit von Ausgaben und automatisierte Erklärungsvalidierung statt über eine Gültigkeitsschranke für Rechnungen',
  'Diese Analyseseite spiegelt Kenias Tax Procedures Act (Steuerverfahrensgesetz), VAT Act (Mehrwertsteuergesetz) und die zugehörigen Durchführungsverordnungen wider, wie sie über die eigenen Bekanntmachungen, FAQ und Leitfäden der Kenya Revenue Authority sowie Big-4-Steuer-Alerts für Änderungen auf Gesetzesebene bestätigt wurden, mit Stand Anfang August 2026, und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei der KRA (kra.go.ke), über die eTIMS-Support-Kanäle oder bei einem kenianischen Steuerberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.',
  'Kenias Weg führt von Electronic Tax Registers mit Fiskalspeicher (2005) über internetfähige TIMS-Geräte (Verordnung verkündet im September 2020, Einführung ab August 2021, endgültige Frist 30. November 2022) bis zur softwarebasierten eTIMS-Plattform: kostenlose Apps, ein Portal, USSD und APIs, die jede Rechnung in Echtzeit oder nahezu in Echtzeit an die KRA übermitteln. Der Finance Act 2023 (Finanzgesetz 2023) weitete die Pflicht ab dem 1. September 2023 über die mehrwertsteuerlich registrierten Unternehmen hinaus auf jede geschäftlich tätige Person aus, und seit dem 1. Januar 2026 validiert die KRA Einkommensteuererklärungen Zeile für Zeile gegen die daraus entstehenden Daten.',
  'Eine konforme kenianische elektronische Steuerrechnung wird über einen von der KRA kontrollierten Kanal erzeugt (eTIMS-Portal, App, USSD oder eine OSCU/VSCU-Systemintegration) und bei Ausstellung an die KRA übermittelt. Zu den Pflichtinhalten gehören die PIN des Verkäufers, die PIN des Käufers, wenn dieser die Ausgabe oder die Vorsteuer geltend machen wird, eindeutige System- und Rechnungskennungen sowie ein QR-Code zur Verifizierung. Die KRA beschreibt die Übermittlung als in Echtzeit oder nahezu in Echtzeit; auf das genaue technische Format legt sich diese Seite nicht fest, da sich die öffentlichen Quellen widersprechen (siehe Hinweis unten).',
  'Seit dem 1. September 2023 erfasst die Pflicht jede Person, die in Kenia ein Geschäft betreibt -- Gesellschaften, Personengesellschaften und Einzelunternehmer, einschließlich derer, die nur Mieteinnahmen versteuern, der Turnover Tax unterliegen oder nur Einkommensteuer zahlen, nicht nur die mehrwertsteuerlich Registrierten. Unternehmen mit einem Jahresumsatz von höchstens KES 5 Millionen müssen sich nicht direkt anmelden: Ihre geschäftlichen Käufer müssen stattdessen für diese Einkäufe selbst Reverse-Rechnungen (käuferseitig ausgestellt) erzeugen. Zu den ausgenommenen Transaktionsarten gehören Arbeitsentgelte, Importe, Zinsen, Flugtickets im Passagierverkehr, Zahlungen mit abgeltender Quellensteuer und Lieferungen von Gebietsfremden ohne kenianische Betriebsstätte.',
  'Jedes in Kenia tätige Unternehmen sollte bereits auf eTIMS angemeldet sein -- das straffreie Onboarding-Fenster schloss am 31. März 2024. Die aktuelle Compliance-Frage ist die Datenqualität: Seit dem 1. Januar 2026 validiert die KRA deklarierte Einnahmen und Ausgaben gegen eTIMS-, Quellensteuer- und Zolldaten. Die Bücher vor der Abgabe mit den eTIMS-Daten abzugleichen und nicht konforme Lieferantenrechnungen unterjährig zurückzuweisen, ist daher jetzt die Kerndisziplin.',
  'Kenia setzt das Regime weniger über eine Gültigkeitsschranke für Rechnungen durch als über das Geld: eine gesetzliche Strafe in Höhe des Zweifachen der geschuldeten Steuer bei Verstößen, die Versagung einkommensteuerlicher Abzüge für Ausgaben ohne eTIMS-Rechnung (seit Januar 2024), die Versagung des Vorsteuerabzugs, vorenthaltene Tax Compliance Certificates (Steuerkonformitätsbescheinigungen) und -- seit Januar 2026 -- die automatisierte Versagung bei der Abgabe, wenn die deklarierten Zahlen nicht mit den eTIMS-Daten übereinstimmen.',
  'Kenia verlangt elektronische Steuerrechnungen von allen mehrwertsteuerlich registrierten Unternehmen seit dem 30. November 2022 (TIMS) und von ALLEN Unternehmen -- auch ohne MwSt.-Registrierung -- seit dem 1. September 2023 (eTIMS, über kostenlose Portal-, App-, USSD- und API-Kanäle). Die Durchsetzung ist finanziell statt gültigkeitsbasiert: Ausgaben ohne eTIMS-Rechnung sind seit Januar 2024 nicht abzugsfähig, und ab dem 1. Januar 2026 gleicht die KRA jede Einkommensteuererklärung mit den eTIMS-Rechnungsdaten, Quellensteueraufzeichnungen und Zollimporten ab. Kleine Lieferanten (Umsatz <= KES 5 Mio.) werden indirekt über die verpflichtende käuferseitige Rechnungsstellung erfasst.',
  '🇰🇪'
FROM countries WHERE code = 'KE';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '30. Nov. 2022', 'Elektronische Steuerrechnungen für alle mehrwertsteuerlich registrierten Unternehmen verpflichtend (TIMS)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 0;
