INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2024', 'Ausgaben ohne eTIMS-Rechnung sind bei der Einkommensteuer nicht mehr abzugsfähig' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '508.413', 'Auf eTIMS angemeldete Steuerpflichtige zum 30. September 2025 (KRA; Ziel: 1 Million)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2026', 'Die KRA validiert Einkommensteuererklärungen gegen eTIMS-, Quellensteuer- und Zolldaten' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Übermittlungsmodell', '[["Rechnungserzeugung", "Über einen von der KRA kontrollierten eTIMS-Kanal (Portal, App, USSD oder OSCU/VSCU-Systemintegration) -- keine freie ERP-Ausgabe"], ["Übermittlung", "In Echtzeit oder nahezu in Echtzeit an die KRA bei Ausstellung (eigene Beschreibung der KRA)"], ["Pflichtinhalte", "PIN des Verkäufers; PIN des Käufers (wenn der Käufer die Ausgabe/Vorsteuer geltend macht); Seriennummer; Datum und Uhrzeit von Ausstellung und Lieferung; Artikelcode, Beschreibung, Menge, Einheit; Steuersatz; Summen; eindeutige System- und Rechnungskennungen; QR-Code"], ["Verifizierung", "Der QR-Code ermöglicht jedem Kunden, die Gültigkeit der Rechnung bei der KRA zu prüfen"]]', 'Die öffentlichen Quellen widersprechen sich beim genauen technischen Format (strukturiertes XML laut einem Branchenbriefing gegenüber einer JSON-REST-API laut Integratorendokumentation) -- diese Seite legt sich bewusst auf keines von beiden fest. Bestätigt sind der von der KRA kontrollierte Erzeugungskanal und die Übermittlung bei Ausstellung.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Lösungskanäle (alle kostenlos von der KRA)', '[["eTIMS Online Portal", "etims.kra.go.ke -- Dienstleistungsunternehmen mit <= 10 Rechnungen/Monat"], ["eTIMS Client", "Windows-/Android-Software für Waren- und Mischbetriebe; unterstützt mehrere Filialen und Kassen"], ["eTIMS Lite", "Für Steuerpflichtige ohne MwSt.-Registrierung: Web über eCitizen, mobile App oder USSD *222# (kein Internet erforderlich)"], ["Systemintegration", "OSCU (KRA-gehostet, Onlinesysteme) oder VSCU (kundengehostet, hohes Volumen) per API; Sandbox unter etims-sbx.kra.go.ke"], ["Reverse Invoicing", "Käuferseitige Rechnungsstellung für Einkäufe von kleinen Lieferanten (Umsatz <= KES 5 Mio.)"]]', 'Seit Februar 2025 erfolgt das Onboarding vollständig im Selbstbedienungsverfahren, und ein Unternehmen kann mehrere Lösungen gleichzeitig betreiben (KRA-Pressemitteilung). Die Software ist kostenlos; Gebühren von Drittanbieter-Integratoren können anfallen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wer die Pflicht erfüllen muss', '[["Alle Unternehmen (seit 1. Sep. 2023)", "Jede geschäftlich tätige Person -- Gesellschaften, Personengesellschaften, Einzelunternehmer, einschließlich derer, die nur Mieteinnahmen versteuern, der Turnover Tax unterliegen oder nur Einkommensteuer zahlen (TPA Abschn. 23A, Finance Act 2023)"], ["Mehrwertsteuerlich registrierte Unternehmen", "Pflicht seit 30. Nov. 2022 (TIMS); seit 1. Juni 2023 berechtigen nur E-Rechnungen zum Vorsteuerabzug"], ["Kleine Lieferanten (Umsatz <= KES 5 Mio.)", "Keine direkte Onboarding-Pflicht -- geschäftliche Käufer müssen stattdessen selbst Reverse-Rechnungen ausstellen (verpflichtend seit 27. Dez. 2024)"], ["Ausgenommene Transaktionen", "Arbeitsentgelte, Importe, Zinsen, Flugtickets im Passagierverkehr, Zahlungen mit abgeltender Quellensteuer, Lieferungen von Gebietsfremden ohne kenianische Betriebsstätte"], ["Gebietsfremde digitale Anbieter", "Vom eTIMS-System selbst befreit, müssen aber weiterhin Rechnungen mit Wert- und Steuerausweis ausstellen"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Rechnungsfluss', 'Eine konforme kenianische E-Rechnung durchläuft folgende Abfolge:', 'Offline-Resilienz ist eingebaut: eTIMS Client und VSCU stellen bei Verbindungsverlust weiter Rechnungen aus und übermitteln nach Wiederverbindung; ein Systemausfall muss der KRA innerhalb von 24 Stunden schriftlich gemeldet werden.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die Rechnung in einem eTIMS-Kanal erzeugen (Portal, App, USSD oder integriertes System)' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die Rechnungsdaten werden validiert und in Echtzeit oder nahezu in Echtzeit an die KRA übermittelt, mit eindeutigen Kennungen und QR-Code versehen' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Der Käufer erhält die konforme Rechnung -- mit der PIN des Käufers, wenn ein Abzug oder eine Vorsteuergeltendmachung folgen wird' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Die übermittelten Daten speisen vorausgefüllte MwSt.-Erklärungen und die Aufzeichnungen der KRA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Ab dem 1. Jan. 2026: Einkommensteuererklärungen werden gegen eTIMS-Verkaufs-/Einkaufsdaten, Quellensteueraufzeichnungen und Zollimporte validiert' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Gesetzliche Sanktionen', '[["Verstoß gegen die E-Invoicing-Pflicht", "Strafe in Höhe des Zweifachen der geschuldeten Steuer (Finance Act 2023)"], ["Unterlassene Integration mit dem Datensystem der KRA, wo vorgeschrieben (> KES 5 Mio. Umsatz)", "Bis zu KES 100.000 pro Monat (Tax Laws (Amendment) Act 2024)"], ["Umgang mit Systemausfällen", "Schriftliche Meldung an die KRA innerhalb von 24 Stunden; Verkäufe werden über vorgeschriebene Alternativwege erfasst (Regulations 2024)"]]', 'Die Gesetzesnorm für die Strafe in Höhe des Zweifachen der geschuldeten Steuer wird üblicherweise als TPA Abschn. 86 zitiert, wurde in dieser Rechercherunde jedoch nicht gegen den konsolidierten Gesetzestext verifiziert -- die Strafhöhe selbst ist durch Big-4-Analysen des Finance Act 2023 bestätigt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Das finanzielle Durchsetzungsnetz', '[["Einkommensteuerabzüge", "Ausgaben ohne über eTIMS erzeugte Rechnung sind nicht abzugsfähig (ITA Abschn. 16(1)(c), seit 1. Jan. 2024)"], ["Vorsteuer", "Nur elektronische Steuerrechnungen berechtigen zu Vorsteuerabzug und Erstattungen (durchgesetzt seit 1. Juni 2023)"], ["Tax Compliance Certificates", "Werden nicht konformen Steuerpflichtigen vorenthalten -- eine praktische Hürde für Ausschreibungen und Bankbeziehungen"], ["Erklärungsvalidierung (seit 1. Jan. 2026)", "Die KRA setzt den höheren Wert aus deklarierten und eTIMS-Einnahmen sowie den niedrigeren Wert aus deklarierten und eTIMS-Ausgaben an -- unbelegte Beträge werden bei der Abgabe administrativ versagt"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔍 Was wir nicht bestätigen konnten', '[["Strafmilderung durch den Finance Act 2026", "Eine berichtete Änderung vom Zweifachen der geschuldeten Steuer auf 5 % der geschuldeten Steuer (mind. KES 100.000 Unternehmen / KES 10.000 Privatpersonen) geht auf eine einzelne Kanzleianalyse zurück -- als plausibel, nicht bestätigt zu behandeln"], ["Genaues technisches Format", "XML vs. JSON-API -- die Quellen widersprechen sich; ungeklärt"], ["Datum der Pflicht zu vorausgefüllten MwSt.-Erklärungen", "Das behauptete Pflichtdatum 1. Jan. 2025 ist nur sekundär belegt (die KRA-Zahl von 162.000 Nutzern der automatisierten Erklärung ist bestätigt, das Pflichtdatum nicht)"], ["Aufbewahrungsfrist", "Eine digitale Aufbewahrungsfrist von 5 Jahren wird in der Branche genannt, aber in dieser Runde wurde keine KRA-Seite gefunden, die sie bestätigt"]]', 'Die hier aufgeführten Punkte sind nach dem Quellenstandard dieser Website aus der Meilenstein-Chronik und der obigen Zusammenfassung ausgeschlossen -- sie werden aufgelistet, damit Sie wissen, was doppelt zu prüfen ist, statt stillschweigend wegzufallen.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Registrieren Sie sich auf eTIMS', 'Melden Sie sich unter etims.kra.go.ke mit Ihrer KRA-PIN (iTax-Zugangsdaten) an. Kleine bzw. nicht mehrwertsteuerlich registrierte Steuerpflichtige können stattdessen eTIMS Lite über eCitizen im Web, die mobile App oder USSD *222# ganz ohne Internetverbindung nutzen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Wählen Sie Ihre Lösung und reichen Sie den Serviceantrag ein', 'Wählen Sie den Kanal, der zu Ihrem Unternehmen passt (Portal, eTIMS Client, Lite oder Systemintegration), und reichen Sie den Serviceantrag mit dem unterschriebenen Verpflichtungsformular und einer Ausweiskopie des Geschäftsführers oder Inhabers ein. Das Onboarding ist seit Februar 2025 vollständig Selbstbedienung, und Sie können mehrere Lösungen gleichzeitig betreiben.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Integration geplant? Testen Sie zuerst in der Sandbox', 'System-zu-System-Integrationen (OSCU für KRA-gehostet, VSCU für kundengehostetes hohes Volumen) müssen vor der Produktionsfreigabe gegen die Sandbox unter etims-sbx.kra.go.ke getestet werden; die Freigabe wird per SMS bestätigt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bringen Sie die Datendetails in Ordnung', 'Konfigurieren Sie die Rechnungslayouts für die Pflichtinhalte -- insbesondere die PIN des Käufers auf jeder Rechnung, die dieser für einen Abzug oder eine Vorsteuergeltendmachung verwenden wird -- und richten Sie die käuferseitige Rechnungsstellung für Einkäufe von kleinen Lieferanten ein. Schulen Sie Vertrieb und Kreditoren-/Debitorenbuchhaltung: Eine fehlende PIN kostet Ihren Kunden jetzt echtes Geld.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Gleichen Sie ab, bevor Sie einreichen', 'Seit dem 1. Januar 2026 validiert die KRA Erklärungen automatisch gegen die eTIMS-Daten. Gleichen Sie Ihre Bücher das ganze Jahr über mit den eTIMS-Verkaufs- und Einkaufsaufzeichnungen ab -- und fordern Sie konforme E-Rechnungen von Lieferanten ein, wenn die Ausgabe anfällt, nicht erst bei der Abgabe.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'eTIMS-Steuerzahlerportal' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'iTax (Abgabe der Steuererklärungen)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'KRA -- Leitfaden zu den eTIMS-Lösungen' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 2;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-tims-regulations-2020', 'de',
  'Verordnung über elektronische Steuerrechnungen verkündet (TIMS)',
  'Die VAT (Electronic Tax Invoice) Regulations, 2020 (Verordnung über die elektronische Steuerrechnung; Legal Notice Nr. 189 vom 25. September 2020) schufen die Rechtsgrundlage für Kenias Tax Invoice Management System (TIMS): Mehrwertsteuerlich registrierte Unternehmen sollten ihre alten Electronic Tax Registers mit Fiskalspeicher (im Einsatz seit 2005) durch internetfähige Geräte ersetzen, die jede Rechnung validieren und in Echtzeit oder nahezu in Echtzeit an die Kenya Revenue Authority (KRA) übermitteln. Die eigentliche Einführung begann am 1. August 2021 mit einem 12-monatigen Migrationsfenster.',
  '["Keine unmittelbare Pflicht zum Zeitpunkt der Verkündung -- das Migrationsfenster öffnete am 1. August 2021.", "Mehrwertsteuerlich registrierte Unternehmen mussten die Umstellung auf ein TIMS-konformes ETR-Gerät planen (Typen A-D, je nach Geschäftsart und Volumen)."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-tims-mandatory-2022', 'de',
  'Elektronische Steuerrechnungen für alle mehrwertsteuerlich registrierten Unternehmen verpflichtend',
  'Nach einem einjährigen Migrationsfenster (ab dem 1. August 2021) und einer per öffentlicher Bekanntmachung gewährten Verlängerung war der 30. November 2022 die endgültige Frist, bis zu der jedes mehrwertsteuerlich registrierte Unternehmen in Kenia elektronische Steuerrechnungen über TIMS-konforme Geräte ausstellen musste, validiert und bei Ausstellung an die KRA übermittelt. Seit dem 1. Juni 2023 setzt die KRA das Regime konsequent durch: Nur elektronische Steuerrechnungen werden zur Geltendmachung des Vorsteuerabzugs und für Erstattungen anerkannt, und nicht konformen Steuerpflichtigen werden die Tax Compliance Certificates (Steuerkonformitätsbescheinigungen) vorenthalten.',
  '["Stellen Sie sicher, dass jedes Verkaufssystem Rechnungen über TIMS/eTIMS mit KRA-Validierung ausstellt.", "Prüfen Sie, ob eingehende Lieferantenrechnungen gültige elektronische Steuerrechnungen sind -- nicht konforme Einkaufsrechnungen berechtigen nicht zum Vorsteuerabzug.", "Besteht eine Compliance-Lücke, wenden Sie sich frühzeitig an die KRA: Nicht konformen Unternehmen werden die Tax Compliance Certificates vorenthalten."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-etims-all-businesses-2023', 'de',
  'eTIMS auf ALLE Unternehmen ausgeweitet -- auch ohne MwSt.-Registrierung',
  'Der Finance Act 2023 (Finanzgesetz 2023) fügte Abschnitt 23A in den Tax Procedures Act (Steuerverfahrensgesetz) ein und weitete die Pflicht zur elektronischen Steuerrechnung über die mehrwertsteuerlich registrierten Steuerpflichtigen hinaus auf jede Person aus, die in Kenia ein Geschäft betreibt -- Gesellschaften, Personengesellschaften und Einzelunternehmer, einschließlich derer, die nur Mieteinnahmen versteuern, der Turnover Tax unterliegen oder nur Einkommensteuer zahlen -- mit Wirkung zum 1. September 2023. Die kostenlosen eTIMS-Softwarekanäle der KRA (Portal, App, USSD *222# über eTIMS Lite) machten Hardwaregeräte überflüssig; das straffreie Onboarding-Fenster für Unternehmen ohne MwSt.-Registrierung schloss am 31. März 2024. Unternehmen mit einem Umsatz von höchstens KES 5 Millionen müssen sich nicht direkt anmelden -- stattdessen müssen ihre Käufer den Einkauf per Reverse Invoicing (käuferseitig ausgestellte Rechnung) erfassen.',
  '["Jedes Unternehmen -- mit oder ohne MwSt.-Registrierung -- sollte auf eTIMS angemeldet sein (Portal, App, eCitizen Lite oder USSD *222#).", "Kleine Lieferanten (Umsatz <= KES 5 Mio.): Rechnen Sie damit, dass Ihre Geschäftskunden für Einkäufe bei Ihnen selbst Reverse-Rechnungen ausstellen.", "Käufer, die bei kleinen, nicht angemeldeten Lieferanten einkaufen, müssen käuferseitig ausgestellte Rechnungen über eTIMS erzeugen."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-deductibility-2024', 'de',
  'Ohne eTIMS-Rechnung kein steuerlicher Abzug',
  'Seit dem 1. Januar 2024 versagt Abschnitt 16(1)(c) des Income Tax Act (Einkommensteuergesetz, in der Fassung des Finance Act 2023) den Abzug für jede Betriebsausgabe, die nicht durch eine über TIMS/eTIMS erzeugte elektronische Steuerrechnung belegt ist. Dies ist Kenias schärfster Durchsetzungsmechanismus: Statt nur die Aussteller zu kontrollieren, macht er jeden geschäftlichen Käufer zum Vollstrecker, denn eine Papier- oder nicht konforme Rechnung eines Lieferanten kostet den Käufer nun den einkommensteuerlichen Abzug für die gesamte Ausgabe.',
  '["Weisen Sie Lieferantenrechnungen zurück, die nicht über eTIMS erzeugt wurden -- sie kosten Sie den einkommensteuerlichen Abzug.", "Stellen Sie sicher, dass Ihre eigenen Rechnungen die PIN des Käufers tragen, wenn dieser die Ausgabe geltend machen wird.", "Gleichen Sie Ihre Ausgabenaufzeichnungen vor Abgabe der Einkommensteuererklärung mit den eTIMS-Einkaufsdaten ab."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-eti-regulations-2024', 'de',
  'Electronic Tax Invoice Regulations 2024 im Amtsblatt verkündet',
  'Die Tax Procedures (Electronic Tax Invoice) Regulations, 2024 (Verordnung über die elektronische Steuerrechnung; Legal Notice Nr. 64, verkündet am 3. Mai 2024) kodifizierten die operativen Details des eTIMS-Regimes: verpflichtende Rechnungsinhalte (PIN des Verkäufers, PIN des Käufers, wenn dieser die Ausgabe geltend machen wird, eindeutige System- und Rechnungskennungen, QR-Code), eine 24-Stunden-Regel zur schriftlichen Meldung von Systemausfällen sowie die Ausnahmen vom Anwendungsbereich (Arbeitsentgelte, Importe, Zinsen, Flugtickets, Zahlungen mit abgeltender Quellensteuer und Lieferungen von Gebietsfremden ohne kenianische Betriebsstätte). Bemerkenswert: Eine im Entwurf vorgesehene vollständige Befreiung für Unternehmen mit weniger als KES 5 Millionen Umsatz wurde gestrichen -- die Pflicht geht stattdessen auf den Käufer über.',
  '["Überprüfen Sie, ob Ihre Rechnungslayouts alle Pflichtfelder enthalten, einschließlich QR-Code und, wo relevant, der PIN des Käufers.", "Richten Sie einen Prozess ein, um die KRA bei Systemausfällen innerhalb von 24 Stunden zu benachrichtigen.", "Ermitteln Sie, welche Ihrer Transaktionsarten unter die Ausnahmen der Verordnung fallen."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-reverse-invoicing-2024', 'de',
  'Käuferseitige Rechnungsstellung bei Einkäufen von kleinen Lieferanten verpflichtend',
  'Der Tax Procedures (Amendment) Act 2024 und der Tax Laws (Amendment) Act 2024 (beide wirksam ab dem 27. Dezember 2024) formalisierten das Reverse Invoicing: Geschäftliche Käufer müssen für Einkäufe von Lieferanten mit einem Jahresumsatz von höchstens KES 5 Millionen selbst elektronische Rechnungen über eTIMS ausstellen, und die KRA erhielt die Befugnis, für Unternehmen mit mehr als KES 5 Millionen Umsatz die Integration der Datensysteme zu erzwingen, abgesichert durch eine Strafe von bis zu KES 100.000 pro Monat bei unterlassener Integration.',
  '["Wenn Sie bei kleinen Lieferanten einkaufen, richten Sie in eTIMS die käuferseitige Rechnungsstellung für diese Einkäufe ein.", "Unternehmen mit mehr als KES 5 Mio. Umsatz: Bereiten Sie sich auf die von der KRA erzwungene Systemintegration vor, falls noch nicht integriert."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-return-validation-2026', 'de',
  'Die KRA gleicht jede Einkommensteuererklärung mit den eTIMS-Daten ab',
  'Gemäß einer öffentlichen Bekanntmachung der KRA vom 10. November 2025 werden ab dem 1. Januar 2026 die in Einkommensteuererklärungen (ab dem Veranlagungsjahr 2025) deklarierten Einnahmen und Ausgaben gegen die TIMS/eTIMS-Rechnungsdaten, Quellensteueraufzeichnungen und Zoll-Importdaten validiert. In der Praxis setzt die KRA den höheren Wert aus deklarierten Einnahmen und eTIMS-Verkaufsdaten sowie den niedrigeren Wert aus deklarierten Ausgaben und eTIMS-Einkaufsdaten an -- unbelegte Ausgaben werden daher bereits bei der Abgabe administrativ versagt. Damit wird die seit Januar 2024 geltende Regel "ohne eTIMS-Rechnung kein Abzug" in nationalem Maßstab operationalisiert.',
  '["Gleichen Sie Ihre Bücher VOR der Abgabe mit den eTIMS-Verkaufs- und Einkaufsdaten ab -- Abweichungen treten jetzt automatisch zutage.", "Fordern Sie konforme E-Rechnungen von Lieferanten während des Jahres ein, nicht erst bei der Abgabe.", "Bestätigen Sie, dass Quellensteuergutschriften und Zoll-Importdaten mit Ihren deklarierten Zahlen übereinstimmen."]'
);

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr',
  'Évolution CTC du matériel vers le logiciel : facturation fiscale électronique obligatoire pour les entreprises assujetties à la TVA depuis 2022 (TIMS), étendue à TOUTES les entreprises via eTIMS depuis septembre 2023, et appliquée par la déductibilité des charges et la validation automatisée des déclarations plutôt que par un blocage de la validité des factures',
  'Cette page d''analyse reflète le Tax Procedures Act (loi sur les procédures fiscales), le VAT Act (loi sur la TVA) et les règlements d''application du Kenya, tels que confirmés via les avis, FAQ et guides de la Kenya Revenue Authority elle-même, ainsi que les alertes fiscales des Big-4 pour les changements de niveau législatif, à début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences en vigueur directement auprès de la KRA (kra.go.ke), des canaux d''assistance eTIMS ou d''un conseiller fiscal kényan avant de fonder vos décisions de conformité sur cette page.',
  'Le parcours du Kenya va des caisses enregistreuses fiscales à mémoire fiscale (Electronic Tax Registers, 2005), en passant par les appareils TIMS connectés à internet (règlement publié en septembre 2020, déploiement à partir d''août 2021, date limite définitive le 30 novembre 2022), jusqu''à la plateforme logicielle eTIMS : applications gratuites, portail, USSD et API qui transmettent chaque facture à la KRA en temps réel ou quasi réel. Le Finance Act 2023 (loi de finances 2023) a étendu l''obligation au-delà des entreprises immatriculées à la TVA à toute personne exerçant une activité commerciale à compter du 1er septembre 2023, et depuis le 1er janvier 2026 la KRA valide les déclarations d''impôt sur le revenu ligne par ligne par rapport aux données ainsi produites.',
  'Une facture fiscale électronique kényane conforme est générée via un canal contrôlé par la KRA (portail eTIMS, application, USSD ou une intégration de systèmes OSCU/VSCU) et transmise à la KRA au moment de l''émission. Le contenu obligatoire comprend le PIN du vendeur, le PIN de l''acheteur lorsque celui-ci déduira la charge ou la TVA d''amont, des identifiants uniques de système et de facture, et un code QR de vérification. La KRA décrit la transmission comme en temps réel ou quasi réel ; le format technique exact n''est pas affirmé ici, les sources publiques se contredisant (voir la note ci-dessous).',
  'Depuis le 1er septembre 2023, l''obligation couvre toute personne exerçant une activité commerciale au Kenya -- sociétés, partnerships et entrepreneurs individuels, y compris les contribuables imposés uniquement sur les revenus locatifs, la taxe sur le chiffre d''affaires ou l''impôt sur le revenu, et pas seulement les assujettis immatriculés à la TVA. Les entreprises dont le chiffre d''affaires annuel est inférieur ou égal à 5 millions de KES ne sont pas tenues de s''enrôler directement : leurs acheteurs professionnels doivent à la place auto-émettre des factures inversées (à l''initiative de l''acheteur) pour ces achats. Les types de transactions exclus comprennent les rémunérations, les importations, les intérêts, la billetterie aérienne de passagers, les paiements soumis à une retenue à la source libératoire et les livraisons de non-résidents sans établissement stable au Kenya.',
  'Toute entreprise opérant au Kenya devrait déjà être sur eTIMS -- la fenêtre d''enrôlement sans pénalité s''est refermée le 31 mars 2024. La question de conformité du moment est la qualité des données : depuis le 1er janvier 2026, la KRA valide les revenus et charges déclarés par rapport aux données eTIMS, de retenue à la source et douanières ; rapprocher vos livres des données eTIMS avant le dépôt et refuser en cours d''année les factures fournisseurs non conformes est désormais la discipline centrale.',
  'Le Kenya fait respecter le régime moins par un blocage de la validité des factures que par l''argent : une pénalité légale du double de l''impôt dû en cas de non-conformité, le refus des déductions d''impôt sur le revenu pour les charges sans facture eTIMS (depuis janvier 2024), le refus de la déduction de la TVA d''amont, la rétention des certificats de conformité fiscale (Tax Compliance Certificates) et -- depuis janvier 2026 -- le rejet automatisé au moment du dépôt lorsque les chiffres déclarés ne correspondent pas aux données eTIMS.',
  'Le Kenya exige des factures fiscales électroniques de toutes les entreprises immatriculées à la TVA depuis le 30 novembre 2022 (TIMS), et de TOUTES les entreprises -- y compris non immatriculées à la TVA -- depuis le 1er septembre 2023 (eTIMS, via des canaux gratuits : portail, application, USSD et API). L''application est financière plutôt que fondée sur la validité : les charges sans facture eTIMS ne sont pas déductibles depuis janvier 2024, et depuis le 1er janvier 2026 la KRA recoupe chaque déclaration d''impôt sur le revenu avec les données de facturation eTIMS, les registres de retenues à la source et les importations douanières. Les petits fournisseurs (chiffre d''affaires <= 5 millions de KES) sont couverts indirectement via la facturation obligatoire à l''initiative de l''acheteur.',
  '🇰🇪'
FROM countries WHERE code = 'KE';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '30 nov. 2022', 'Factures fiscales électroniques obligatoires pour toutes les entreprises immatriculées à la TVA (TIMS)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er sept. 2023', 'L''obligation s''étend à TOUTES les entreprises, y compris non immatriculées à la TVA (eTIMS)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2024', 'Les charges sans facture eTIMS deviennent non déductibles de l''impôt sur le revenu' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '508 413', 'Contribuables enrôlés sur eTIMS au 30 septembre 2025 (KRA ; objectif : 1 million)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2026', 'La KRA valide les déclarations d''impôt sur le revenu par rapport aux données eTIMS, de retenue à la source et douanières' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'KE' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et modèle de transmission', '[["Génération de la facture", "Via un canal eTIMS contrôlé par la KRA (portail, application, USSD ou intégration de systèmes OSCU/VSCU) -- pas une sortie ERP libre"], ["Transmission", "En temps réel ou quasi réel vers la KRA au moment de l''émission (description de la KRA elle-même)"], ["Contenu obligatoire", "PIN du vendeur ; PIN de l''acheteur (lorsque l''acheteur déduit la charge/la TVA d''amont) ; numéro de série ; date et heure d''émission et de livraison ; code article, description, quantité, unité ; taux de taxe ; totaux ; identifiants uniques de système et de facture ; code QR"], ["Vérification", "Le code QR permet à tout client de vérifier la validité de la facture auprès de la KRA"]]', 'Les sources publiques se contredisent sur le format technique exact (XML structuré selon un briefing sectoriel contre une API REST JSON selon la documentation d''intégrateurs) -- cette page s''abstient délibérément de trancher. Ce qui est confirmé, c''est le canal de génération contrôlé par la KRA et la transmission au moment de l''émission.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Canaux de solution (tous gratuits auprès de la KRA)', '[["eTIMS Online Portal", "etims.kra.go.ke -- entreprises de services émettant <= 10 factures/mois"], ["eTIMS Client", "Logiciel Windows/Android pour les entreprises de biens et mixtes ; prend en charge plusieurs succursales et caisses"], ["eTIMS Lite", "Pour les contribuables non assujettis à la TVA : web via eCitizen, application mobile ou USSD *222# (aucun accès internet requis)"], ["Intégration de systèmes", "OSCU (hébergé par la KRA, systèmes en ligne) ou VSCU (hébergé par le client, gros volumes) via API ; sandbox sur etims-sbx.kra.go.ke"], ["Facturation inversée", "Facturation à l''initiative de l''acheteur pour les achats auprès de petits fournisseurs (chiffre d''affaires <= 5 millions de KES)"]]', 'Depuis février 2025, l''enrôlement est entièrement en libre-service et une entreprise peut utiliser plusieurs solutions simultanément (communiqué de presse de la KRA). Le logiciel est gratuit ; des frais d''intégrateurs tiers peuvent s''appliquer.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui doit se conformer', '[["Toutes les entreprises (depuis le 1er sept. 2023)", "Toute personne exerçant une activité commerciale -- sociétés, partnerships, entrepreneurs individuels, y compris les contribuables imposés uniquement sur les revenus locatifs, la taxe sur le chiffre d''affaires ou l''impôt sur le revenu (art. 23A du TPA, Finance Act 2023)"], ["Entreprises immatriculées à la TVA", "Sous obligation depuis le 30 nov. 2022 (TIMS) ; seules les factures électroniques justifient la déduction de la TVA d''amont depuis le 1er juin 2023"], ["Petits fournisseurs (chiffre d''affaires <= 5 millions de KES)", "Pas d''obligation d''enrôlement direct -- les acheteurs professionnels doivent auto-émettre des factures inversées à la place (obligatoire depuis le 27 déc. 2024)"], ["Transactions exclues", "Rémunérations, importations, intérêts, billetterie aérienne de passagers, paiements à retenue à la source libératoire, livraisons de non-résidents sans établissement stable kényan"], ["Fournisseurs numériques non résidents", "Exemptés du système eTIMS lui-même, mais doivent néanmoins émettre des factures indiquant la valeur et la taxe"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux de la facture', 'Une facture électronique kényane conforme suit la séquence suivante :', 'La résilience hors ligne est intégrée : eTIMS Client et VSCU continuent de facturer pendant les pertes de connectivité et transmettent à la reconnexion ; toute panne du système doit être notifiée par écrit à la KRA sous 24 heures.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND lc.section = 'scope_transmission' AND lc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Générer la facture dans un canal eTIMS (portail, application, USSD ou système intégré)' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Les données de la facture sont validées et transmises à la KRA en temps réel ou quasi réel, avec identifiants uniques et code QR appliqués' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'L''acheteur reçoit la facture conforme -- portant le PIN de l''acheteur lorsqu''une déduction ou une récupération de TVA d''amont suivra' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Les données transmises alimentent les déclarations de TVA préremplies et les registres de la KRA' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Depuis le 1er janv. 2026 : les déclarations d''impôt sur le revenu sont validées par rapport aux données de ventes/achats eTIMS, aux registres de retenues et aux importations douanières' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lc ON ls.card_id = lc.id JOIN countries c ON lc.country_id = c.id WHERE c.code = 'KE' AND ls.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Pénalités légales', '[["Non-respect de l''obligation de facturation électronique", "Pénalité du double de l''impôt dû (Finance Act 2023)"], ["Défaut d''intégration au système de données de la KRA lorsqu''elle est exigée (> 5 millions de KES de chiffre d''affaires)", "Jusqu''à 100 000 KES par mois (Tax Laws (Amendment) Act 2024)"], ["Gestion des pannes du système", "Notification écrite à la KRA sous 24 heures ; ventes enregistrées par les moyens alternatifs prescrits (Regulations 2024)"]]', 'L''article de loi de la pénalité du double de l''impôt dû est couramment cité comme l''art. 86 du TPA, mais n''a pas été vérifié par rapport au texte consolidé de la loi lors de cette série de recherches -- le montant de la pénalité lui-même est confirmé par les analyses des Big-4 du Finance Act 2023.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Le dispositif d''application financière', '[["Déductions d''impôt sur le revenu", "Les charges sans facture générée via eTIMS ne sont pas déductibles (art. 16(1)(c) de l''ITA, depuis le 1er janv. 2024)"], ["TVA d''amont", "Seules les factures fiscales électroniques justifient la déduction et le remboursement de la TVA d''amont (appliqué depuis le 1er juin 2023)"], ["Tax Compliance Certificates", "Refusés aux contribuables non conformes -- un obstacle pratique aux appels d''offres et aux relations bancaires"], ["Validation des déclarations (depuis le 1er janv. 2026)", "La KRA retient le plus élevé entre les revenus déclarés et eTIMS, et le plus faible entre les charges déclarées et eTIMS -- les montants non justifiés font l''objet d''un rejet administratif au dépôt"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔍 Ce que nous n''avons pas pu confirmer', '[["Adoucissement des pénalités par le Finance Act 2026", "Un passage rapporté du double de l''impôt dû à 5 % de l''impôt dû (min. 100 000 KES sociétés / 10 000 KES particuliers) remonte à une seule analyse de cabinet d''avocats -- à traiter comme plausible, non confirmé"], ["Format technique exact", "XML contre API JSON -- les sources se contredisent ; non résolu"], ["Date de l''obligation de déclarations de TVA préremplies", "La date obligatoire alléguée du 1er janv. 2025 ne repose que sur des sources secondaires (le chiffre de la KRA de 162 000 utilisateurs de la déclaration automatisée est confirmé, la date de l''obligation ne l''est pas)"], ["Période d''archivage", "Une durée de conservation numérique de 5 ans est citée par le secteur, mais aucune page de la KRA la confirmant n''a été trouvée lors de cette série de recherches"]]', 'Les éléments listés ici sont exclus de la chronologie des jalons et du résumé ci-dessus en vertu du standard de sourçage de ce site -- ils sont énumérés pour que vous sachiez quoi revérifier, plutôt que passés sous silence.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'KE' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Inscrivez-vous sur eTIMS', 'Inscrivez-vous sur etims.kra.go.ke avec votre PIN KRA (identifiants iTax). Les petits contribuables ou non assujettis à la TVA peuvent utiliser à la place eTIMS Lite via eCitizen sur le web, l''application mobile ou USSD *222# sans connexion internet.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Choisissez votre solution et soumettez la demande de service', 'Sélectionnez le canal adapté à votre activité (portail, eTIMS Client, Lite ou intégration de systèmes) et soumettez la demande de service avec le formulaire d''engagement signé et une copie de la pièce d''identité du dirigeant ou du propriétaire. L''enrôlement est entièrement en libre-service depuis février 2025, et vous pouvez utiliser plusieurs solutions à la fois.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vous vous intégrez ? Testez d''abord sur le sandbox', 'Les intégrations de système à système (OSCU pour l''hébergement KRA, VSCU pour les gros volumes hébergés par le client) doivent être testées sur le sandbox etims-sbx.kra.go.ke avant l''approbation en production, confirmée par SMS.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Soignez les détails des données', 'Configurez vos maquettes de facture pour le contenu obligatoire -- en particulier le PIN de l''acheteur sur toute facture que celui-ci utilisera pour une déduction ou une récupération de TVA d''amont -- et mettez en place la facturation à l''initiative de l''acheteur pour les achats auprès de petits fournisseurs. Formez les équipes commerciales et comptables (fournisseurs/clients) : un PIN manquant coûte désormais de l''argent réel à votre client.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Rapprochez avant de déposer', 'Depuis le 1er janvier 2026, la KRA valide automatiquement les déclarations par rapport aux données eTIMS. Rapprochez vos livres des registres de ventes et d''achats eTIMS tout au long de l''année -- et réclamez les factures électroniques conformes à vos fournisseurs au moment où la dépense survient, pas au moment du dépôt.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'KE' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Portail du contribuable eTIMS' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'iTax (dépôt des déclarations)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'KRA -- guide des solutions eTIMS' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'KE' AND pt.sort_order = 2;

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-tims-regulations-2020', 'fr',
  'Publication au journal officiel du règlement sur la facture fiscale électronique (TIMS)',
  'Les VAT (Electronic Tax Invoice) Regulations, 2020 (règlement TVA sur la facture fiscale électronique ; Legal Notice n° 189 du 25 septembre 2020) ont créé la base légale du Tax Invoice Management System (TIMS) du Kenya : les entreprises immatriculées à la TVA devraient remplacer leurs anciennes caisses enregistreuses fiscales à mémoire fiscale (Electronic Tax Registers, en service depuis 2005) par des appareils connectés à internet qui valident chaque facture et la transmettent à la Kenya Revenue Authority (KRA) en temps réel ou quasi réel. Le déploiement proprement dit a commencé le 1er août 2021 avec une fenêtre de migration de 12 mois.',
  '["Aucune obligation immédiate au moment de la publication -- la fenêtre de migration s''est ouverte le 1er août 2021.", "Les entreprises immatriculées à la TVA devaient planifier le passage à un appareil ETR conforme à TIMS (types A-D, selon le type d''activité et le volume)."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-tims-mandatory-2022', 'fr',
  'Factures fiscales électroniques obligatoires pour toutes les entreprises immatriculées à la TVA',
  'Après une fenêtre de migration d''un an (à compter du 1er août 2021) et une prolongation annoncée par avis public, le 30 novembre 2022 a été la date limite définitive pour que toute entreprise immatriculée à la TVA au Kenya émette des factures fiscales électroniques via des appareils conformes à TIMS, validées et transmises à la KRA au moment de l''émission. Depuis le 1er juin 2023, la KRA applique le régime avec rigueur : seules les factures fiscales électroniques sont acceptées pour justifier la déduction de la TVA d''amont et les remboursements, et les contribuables non conformes se voient refuser leurs certificats de conformité fiscale (Tax Compliance Certificates).',
  '["Confirmez que chacun de vos systèmes de vente émet les factures via TIMS/eTIMS avec validation de la KRA.", "Vérifiez que les factures fournisseurs entrantes sont des factures fiscales électroniques valides -- les factures d''achat non conformes ne peuvent pas justifier la déduction de la TVA d''amont.", "En cas d''écart de conformité, contactez la KRA sans attendre : les Tax Compliance Certificates sont refusés aux entreprises non conformes."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-etims-all-businesses-2023', 'fr',
  'eTIMS étendu à TOUTES les entreprises -- y compris non immatriculées à la TVA',
  'Le Finance Act 2023 (loi de finances 2023) a inséré l''article 23A dans le Tax Procedures Act (loi sur les procédures fiscales), étendant l''obligation de facture fiscale électronique au-delà des contribuables immatriculés à la TVA à toute personne exerçant une activité commerciale au Kenya -- sociétés, partnerships et entrepreneurs individuels, y compris les contribuables imposés uniquement sur les revenus locatifs, la taxe sur le chiffre d''affaires ou l''impôt sur le revenu -- avec effet au 1er septembre 2023. Les canaux logiciels gratuits eTIMS de la KRA (portail, application, USSD *222# via eTIMS Lite) ont supprimé le besoin d''appareils physiques, avec une fenêtre d''enrôlement sans pénalité pour les entreprises non immatriculées à la TVA, close le 31 mars 2024. Les entreprises dont le chiffre d''affaires est inférieur ou égal à 5 millions de KES ne sont pas tenues de s''enrôler directement -- leurs acheteurs doivent à la place enregistrer l''achat via la facturation inversée (à l''initiative de l''acheteur).',
  '["Toute entreprise -- immatriculée à la TVA ou non -- devrait être enrôlée sur eTIMS (portail, application, eCitizen Lite ou USSD *222#).", "Petits fournisseurs (chiffre d''affaires <= 5 millions de KES) : attendez-vous à ce que vos acheteurs professionnels auto-émettent des factures inversées pour leurs achats auprès de vous.", "Les acheteurs qui s''approvisionnent auprès de petits fournisseurs non enrôlés doivent générer des factures à l''initiative de l''acheteur via eTIMS."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-deductibility-2024', 'fr',
  'Pas de facture eTIMS, pas de déduction fiscale',
  'Depuis le 1er janvier 2024, l''article 16(1)(c) de l''Income Tax Act (loi sur l''impôt sur le revenu), tel que modifié par le Finance Act 2023, rejette toute charge d''exploitation qui n''est pas justifiée par une facture fiscale électronique générée via TIMS/eTIMS. C''est le mécanisme d''application le plus incisif du Kenya : plutôt que de surveiller uniquement les émetteurs, il transforme chaque acheteur professionnel en garant de la conformité, car une facture papier ou non conforme d''un fournisseur coûte désormais à l''acheteur la déduction d''impôt sur le revenu sur la totalité de cette dépense.',
  '["Refusez les factures fournisseurs qui ne sont pas générées via eTIMS -- elles vous coûtent la déduction d''impôt sur le revenu.", "Veillez à ce que vos propres factures portent le PIN de l''acheteur lorsque celui-ci déduira la dépense.", "Rapprochez vos registres de charges des données d''achats eTIMS avant de déposer vos déclarations d''impôt sur le revenu."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-eti-regulations-2024', 'fr',
  'Publication du règlement 2024 sur la facture fiscale électronique',
  'Les Tax Procedures (Electronic Tax Invoice) Regulations, 2024 (règlement sur les procédures fiscales relatif à la facture fiscale électronique ; Legal Notice n° 64, publié le 3 mai 2024) ont codifié le détail opérationnel du régime eTIMS : contenu obligatoire de la facture (PIN du vendeur, PIN de l''acheteur lorsque celui-ci déduira la dépense, identifiants uniques de système et de facture, code QR), une règle de notification écrite sous 24 heures en cas de panne du système, et les exclusions du champ d''application (rémunérations, importations, intérêts, billetterie aérienne, paiements soumis à une retenue à la source libératoire et livraisons de non-résidents sans établissement stable au Kenya). Fait notable, un projet d''exonération totale pour les entreprises de moins de 5 millions de KES de chiffre d''affaires a été abandonné -- l''obligation est reportée sur l''acheteur.',
  '["Vérifiez que vos maquettes de facture comportent tous les champs de contenu obligatoires, y compris le code QR et le PIN de l''acheteur le cas échéant.", "Mettez en place un processus de notification de la KRA sous 24 heures en cas de panne du système.", "Identifiez ceux de vos types de transactions qui relèvent des exclusions du règlement."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-reverse-invoicing-2024', 'fr',
  'Facturation à l''initiative de l''acheteur obligatoire pour les achats auprès de petits fournisseurs',
  'Le Tax Procedures (Amendment) Act 2024 et le Tax Laws (Amendment) Act 2024 (tous deux en vigueur au 27 décembre 2024) ont formalisé la facturation inversée : les acheteurs professionnels doivent auto-émettre des factures électroniques via eTIMS pour les achats auprès de fournisseurs dont le chiffre d''affaires annuel est inférieur ou égal à 5 millions de KES, et la KRA a obtenu le pouvoir d''imposer l''intégration des systèmes de données aux entreprises dépassant 5 millions de KES de chiffre d''affaires, assortie d''une pénalité pouvant atteindre 100 000 KES par mois en cas de défaut d''intégration.',
  '["Si vous achetez auprès de petits fournisseurs, configurez dans eTIMS la facturation à l''initiative de l''acheteur pour ces achats.", "Entreprises dépassant 5 millions de KES de chiffre d''affaires : préparez-vous à l''intégration de systèmes imposée par la KRA si vous n''êtes pas déjà intégrées."]'
);
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES (
  'ke-return-validation-2026', 'fr',
  'La KRA recoupe chaque déclaration d''impôt sur le revenu avec les données eTIMS',
  'Selon un avis public de la KRA du 10 novembre 2025, depuis le 1er janvier 2026 les revenus et charges déclarés dans les déclarations d''impôt sur le revenu (à partir de l''exercice 2025) sont validés par rapport aux données de facturation TIMS/eTIMS, aux registres de retenues à la source et aux registres douaniers d''importation. En pratique, la KRA retient le plus élevé entre les revenus déclarés et les données de ventes eTIMS, et le plus faible entre les charges déclarées et les données d''achats eTIMS -- les charges non justifiées font donc l''objet d''un rejet administratif dès le dépôt. Cela opérationnalise, à l''échelle nationale, la règle « pas de facture eTIMS, pas de déduction » en vigueur depuis janvier 2024.',
  '["Rapprochez vos livres des données de ventes et d''achats eTIMS AVANT le dépôt -- les écarts remontent désormais automatiquement.", "Réclamez les factures électroniques conformes à vos fournisseurs tout au long de l''année, pas au moment du dépôt.", "Confirmez que les crédits de retenue à la source et les registres douaniers d''importation correspondent à vos chiffres déclarés."]'
);
